        email_info = validate_email(email, check_deliverability=False)
        # Normalize the email: local part + @ + domain part in lower case
        normalized_email = f"{email_info.local}@{email_info.domain.lower()}"
        return 200, {"valid": True, "email": normalized_email}
    except EmailNotValidError:
        return 400, {"valid": False, "error": "invalid email"}

